import "core-js/modules/web.dom.iterable";
import { getLocalDetail, getApplicationsCurrent, getListLocal, getApplications } from "@/api/h3c/h3capplication";
export default {
  props: ['keyId'],
  data: function data() {
    return {
      keyword: '',
      form: {},
      id: '',
      availableList: [{
        dictKey: '0',
        dictValue: '可用'
      }, {
        dictKey: '2',
        dictValue: 'Ping不可达'
      }, {
        dictKey: '3',
        dictValue: '协议连接失败'
      }, {
        dictKey: '4',
        dictValue: '未知(显示:–)'
      }],
      healthList: [{
        dictKey: '0',
        dictValue: '正常'
      }, {
        dictKey: '1',
        dictValue: '未知(显示:–)'
      }, {
        dictKey: '2',
        dictValue: ''
      }, {
        dictKey: '3',
        dictValue: '通知'
      }, {
        dictKey: '4',
        dictValue: '警告'
      }, {
        dictKey: '5',
        dictValue: '次要'
      }, {
        dictKey: '6',
        dictValue: '重要'
      }, {
        dictKey: '7',
        dictValue: '紧急'
      }],
      deviceList: [],
      catalogHeight: "calc(100% - 53px)" // 默认值高度：50px搜索框高度（21外边距）
    };
  },
  mounted: function mounted() {
    if (this.keyId) {
      this.form.appId = this.keyId;
    }
    if (this.$route.query.id) {
      this.getDeatil(this.$route.query.id);
    }
    //获取 监控设备列表
    this.getList();
  },
  methods: {
    getList: function getList() {
      var _this2 = this;
      getApplications(1, 100, {
        appType: this.form.appType
      }).then(function (res) {
        var data = res.data;
        _this2.deviceList = data.records;
      }).catch(function () {
        getListLocal(1, 100, {}).then(function (res) {
          var data = res.data;
          _this2.deviceList = data.records;
        });
      });
    },
    getDeatil: function getDeatil(id) {
      var _this = this;
      getApplicationsCurrent(id).then(function (res) {
        _this.form = res.data.data[0];
        //console.log(_this.form.unitData)
        _this.form.unitData.forEach(function (item, uidx) {
          //获取指标组
          item.values.forEach(function (valItem, vidx) {
            //获取指标组
            valItem.forEach(function (val, vvidx) {
              _this.form.unitData[uidx].values[vidx][vvidx].appId = item.headers[vvidx].appId || '';
              _this.form.unitData[uidx].values[vidx][vvidx].appField = item.headers[vvidx].appField || '';
              _this.form.unitData[uidx].values[vidx][vvidx].valueType = item.headers[vvidx].valueType || '';
              _this.form.unitData[uidx].values[vidx][vvidx].valueType = item.headers[vvidx].valueType || '';
              _this.form.unitData[uidx].values[vidx][vvidx].valueUnit = item.headers[vvidx].valueUnit || '';
              _this.form.unitData[uidx].values[vidx][vvidx].unitGroup = item.headers[vvidx].unitGroup || '';
            });
          });
        });
        //console.log(_this.form.unitData)
      });
    },
    getLoaclDeatil: function getLoaclDeatil(id) {
      var _this = this;
      getLocalDetail(id).then(function (res) {
        _this.form = res.data.data[0];
        //console.log(_this.form.unitData)
        _this.form.unitData.forEach(function (item, uidx) {
          //获取指标组
          item.values.forEach(function (valItem, vidx) {
            //获取指标组
            valItem.forEach(function (val, vvidx) {
              _this.form.unitData[uidx].values[vidx][vvidx].appId = item.headers[vvidx].appId || '';
              _this.form.unitData[uidx].values[vidx][vvidx].appField = item.headers[vvidx].appField || '';
              _this.form.unitData[uidx].values[vidx][vvidx].valueType = item.headers[vvidx].valueType || '';
              _this.form.unitData[uidx].values[vidx][vvidx].valueType = item.headers[vvidx].valueType || '';
              _this.form.unitData[uidx].values[vidx][vvidx].valueUnit = item.headers[vvidx].valueUnit || '';
              _this.form.unitData[uidx].values[vidx][vvidx].unitGroup = item.headers[vvidx].unitGroup || '';
            });
          });
        });
        //console.log(_this.form.unitData)
      });
    },
    showDictLable: function showDictLable(code, dictList) {
      //字典回显
      if (dictList != null && code != '') {
        var items = dictList.filter(function (item) {
          return item.dictKey === "" + code;
        });
        if (items != null && items.length > 0) {
          return items[0].dictValue;
        }
      }
      return code;
    },
    modelChange: function modelChange(val) {
      //获取模型
      for (var i = 0; i < this.deviceList.length; i++) {
        var item = this.deviceList[i];
        if (item.id === val) {
          this.form.appType = item.appType;
          this.form.available = item.available;
          this.form.health = item.health;
          this.form.id = item.id;
          this.id = item.id;
          this.getDeatil(this.form.id);
          //this.getLoaclDeatil(this.form.id);
        }
      }
    }
  }
};
